// Spec-style helper: counts how many elements are true.
// In a verification-oriented setting this would be `spec fn` over `Seq<bool>`.
// Here we provide an executable equivalent to support runtime checks.
fn count_true_vec(condition: &[bool]) -> usize {
    condition.iter().filter(|&&b| b).count()
}

// Extracts elements of `arr` where `condition` is true, preserving order.
// Assumes `condition.len() == arr.len()`.
pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    assert!(
        condition.len() == arr.len(),
        "condition and arr must have equal length"
    );

    let expected_len = count_true_vec(&condition);
    let mut result = Vec::<f32>::with_capacity(expected_len);

    for (&c, &x) in condition.iter().zip(arr.iter()) {
        if c {
            result.push(x);
        }
    }

    debug_assert!(
        result.len() == expected_len,
        "result length must equal number of true values in condition"
    );

    result
}

